    "site.admin.seed.intro": "WardSynQ सोबत पाठवलेली क्लिनिकल सामग्री. {signatory} त्यांच्या अचूक वर्तमान सामग्रीवर स्वाक्षरी करत नाही तोपर्यंत प्रत्येक बाब UNAPPROVED असते. स्वाक्षरी केल्याने साइन-ऑफ नोंदवला जातो; यामुळे कोणत्याही सुरक्षा तपासणीचे वर्तन बदलत नाही.",
