    "site.admin.hospital.noteWriters.title": "क्लिनिकल नोट कोण लिहू शकते",
    "site.admin.hospital.noteWriters.intro": "डॉक्टर आणि ॲडमिन नेहमी नोंद लिहू शकतात. रुग्णाच्या टाइमलाइनवर दस्तऐवजीकरण करण्यासाठी आपल्या हॉस्पिटलचा विश्वास असलेल्या इतर कोणत्याही भूमिकेवर टिक करा. यामुळे त्यांना फक्त नोंद लिहिता येते आणि काहीही नाही: हे त्यांना औषध लिहून देणे, ऑर्डर देणे किंवा काहीही बदलण्याची अनुमती देत नाही.",
