    "site.admin.hospital.printLang.intro": "इंग्रजी प्रिंट नेहमी पूर्ण असते आणि तीच अधिकृत मानली जाते. दुसरी भाषा तिच्या शेजारी प्रिंट केली जाते, जी भाषांतर म्हणून चिन्हांकित असते आणि त्यात केवळ मथळे, लेबल्स आणि प्रिस्क्रायबरने निश्चित यादीतून निवडलेल्या रुग्णाच्या सूचना समाविष्ट असतात. औषधांची नावे, डोस, वारंवारता, Diagnoses, Results आणि टाईप केलेले काहीही फक्त इंग्रजीत प्रिंट केले जाते. ज्यांचे भाषांतर अद्याप केलेले नाही ते इंग्रजीत दिसतील.",
